import{U as e,W as t,nt as n,t as r}from"./chunks/framework.DRwsyrlO.js";import"./chunks/assets.DbQFHwAY.js";var i=JSON.parse(`{"title":"从方块开始，走得更远","description":"在 PotgCraft 建造自己的世界。增强生存里盖房、探索、研究红石；科技空岛里发展工业、亲手造船，走向太空。","frontmatter":{"layout":"home","title":"从方块开始，走得更远","description":"在 PotgCraft 建造自己的世界。增强生存里盖房、探索、研究红石；科技空岛里发展工业、亲手造船，走向太空。","hero":{"name":"PotgCraft","text":"从方块开始，走得更远","tagline":"在原版世界留下一座城，或从一座空岛造出自己的飞船。建筑、红石、工业与太空探索，两种玩法，都值得认真玩下去。","actions":[{"theme":"brand","text":"找到你的玩法","link":"/#worlds"},{"theme":"alt","text":"加入 QQ 社区","link":"https://qm.qq.com/q/qcQuFz2AwM"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}`),a={name:`index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<section class="portal-section" aria-labelledby="worlds"><p class="section-kicker">公益 Minecraft 群组服 · 两种玩法</p><h2 id="worlds">想留下作品，也想走得更远。</h2><div class="portal-grid worlds-grid"><a class="portal-card world-card" href="/server-intro.html"><span class="card-eyebrow">增强生存</span><h3>用方块安家，用红石实现想法。</h3><p>从一间小屋到一片聚落，从第一台农场到反复调试的生电工程。在熟悉的原版世界里，给自己的想法留一块地方。</p><div class="card-tags"><span>建筑与探索</span><span>红石生电</span><span>VR 游玩支持</span></div><p class="card-meta">原版客户端可加入 · 当前 Leaf 26.2</p><span class="card-link">看看增强生存</span></a><a class="portal-card world-card" href="/skyblock/"><span class="card-eyebrow">科技空岛</span><h3>亲手造出飞船，然后离开空岛。</h3><p>向虚空抛竿，搭起工厂，把工业成果投入航天研究。等到船体组装完成，空岛之外，还有太空与空间站生活。</p><div class="card-tags"><span>资源成长</span><span>工业自动化</span><span>飞船与空间站</span></div><p class="card-meta">Java 1.21.1 · 需要匹配的科技模组客户端</p><span class="card-link">看看科技空岛</span></a></div></section><section class="portal-section campaign-band" aria-labelledby="build"><div class="campaign-copy"><p class="section-kicker">增强生存 · 把日子建成喜欢的样子</p><h2 id="build">房子可以慢慢盖，<br>工程可以继续改。</h2><p>今天补完屋顶，明天研究一段红石。原版机制与建筑是这里的底色，鞘翅胸甲、便携末影箱和天堂维度，则给日常游玩添些新选择。</p><p>也欢迎戴上 VR，换个视角走进自己和朋友建造的世界。</p><a class="portal-text-link" href="/server-intro.html">走进增强生存</a></div><figure class="campaign-photo"><img src="https://s1.imagehub.cc/images/2026/03/17/7b50c58e5ab32698c1d6d8d83b577cbc.md.png" alt="本站已有的增强生存世界实景" loading="lazy"><figcaption>增强生存世界实景 · 沿用本站原有截图</figcaption></figure></section><section class="portal-section campaign-band campaign-band-reverse" aria-labelledby="beyond"><figure class="campaign-photo space-photo"><a href="/skyblock/#flight"><img src="/images/skyblock/ship-flight.png" alt="玩家自造的方块飞船在星空中航行" width="1920" height="1080" loading="lazy"></a><figcaption>科技空岛实景 · 玩家自造飞船的太空航行</figcaption></figure><div class="campaign-copy"><p class="section-kicker">科技空岛 · 给传统空岛一个新的结局</p><h2 id="beyond">工厂运转之后，<br>还有下一站。</h2><p>齿轮、化工设备、自动合成网络，最终可以服务于同一个想法：把亲手搭出的飞船开向太空，再为下一处据点规划空气、温度和重力。</p><p>从起步资源到宇宙工程，玩法经过适配与拓展。按自己的节奏建设，享受每一段从想法变成实物的过程。</p><a class="portal-text-link" href="/skyblock/">看看空岛之外的世界</a><p class="campaign-note">离岛毕业会改变岛屿归属；岛主毕业会注销原岛并影响队友。出发前请阅读 <a href="/skyblock/graduation.html">毕业规则</a>。</p></div></section><section class="portal-section" aria-labelledby="crafted"><p class="section-kicker">围绕游玩，一点点打磨</p><h2 id="crafted">让不同玩法，接得上彼此。</h2><div class="editorial-grid"><div><h3>资源有来路，发展有联系</h3><p>岛屿任务连接钓鱼芯片与资源成长，工业材料衔接航天研究。每段建设，都能为下一个想法准备条件。</p></div><div><h3>空间站，也能亲手经营</h3><p>为固定空间站设置空气、温度和重力，让太空中的建筑拥有适合生活的环境。</p></div><div><h3>玩家的想法，进入后续开发</h3><p>空间站环境、外星矿源、太空收电，都有来自游玩需求的整合与扩展。遇到值得琢磨的点子，欢迎一起讨论。</p></div></div></section><section class="portal-section community-panel" aria-labelledby="community"><div><p class="section-kicker">PotgCraft 服务器 · 走向群星</p><h2 id="community">下一座建筑，下一条产线，<br>可以一起琢磨。</h2><p>维护这个社区，是想和更多喜欢 Minecraft 的人建立连接。分享作品、讨论机器，也一起经历那些计划之外的瞬间，让建筑之外还有可以记住的故事。</p><p>已有 QQ 群与游戏聊天互通，具体子服覆盖以群内说明为准。</p></div><div class="portal-actions"><a class="portal-button" href="https://qm.qq.com/q/qcQuFz2AwM" target="_blank" rel="noopener noreferrer">加入 QQ 社区</a><a class="portal-text-link" href="/server-intro.html#join">增强生存加入说明</a><a class="portal-text-link" href="/skyblock/#join">科技空岛客户端与加入说明</a></div></section><section class="portal-section campaign-directory" aria-label="玩家资料入口"><p>已经在玩？需要的时候，回来查一查。</p><div class="quick-links"><a href="/guides/">玩法知识库</a><a href="/skyblock/fishing-rewards.html">漂流钓鱼奖池</a><a href="/skyblock/spaceflight.html">航天发展指南</a><a href="/changelog.html">更新日志</a></div></section>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};